import{_ as s,a0 as i,w as r,s as a,ao as u,I as t,a1 as n,A as p,x as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"“Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現 | LCTT x X-CMD","titleTemplate":false,"description":"“Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140716 Simple Dock GNOME Shell Extension Puts Your Fave Apps On The Desktop","title":"“Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現","tag":"201407","desc":""},"relativePath":"201407/20140716 Simple Dock GNOME Shell Extension Puts Your Fave Apps On The Desktop.md","filePath":"[post].md"}'),m={name:"201407/20140716 Simple Dock GNOME Shell Extension Puts Your Fave Apps On The Desktop.md"};function S(d,e,h,k,O,E){const o=i("Link");return r(),a("div",null,[e[12]||(e[12]=u('<h1 id="simple-dock-gnome-shell擴展乾坤大挪移-鍾愛應用桌面展現" tabindex="-1">“Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現 <a class="header-anchor" href="#simple-dock-gnome-shell擴展乾坤大挪移-鍾愛應用桌面展現" aria-label="Permalink to ““Simple Dock” GNOME Shell擴展乾坤大挪移，鍾愛應用桌面展現”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/07/screenshot_815_1.jpg" alt=""></p><p><strong>我愛GNOME Shell，但是我痛恨的是費力從隱藏屏幕中找到我所鍾愛的應用或者在我正運行的應用間切換。</strong></p><p>這麼説，聽起來就像我是個老古董，像是一個UX勒德分子，也像是某個過分沉溺於Unity可用性癮君子，但我，像閲讀本文的許多人一樣，喜歡將app啓動器/切換器放到桌面上。這是一個用户所熟悉並且快捷的工作方式。</p><p>而GNOME Shell，從設計上看，卻完全是個不同的世界。它將所有這一切隱藏起來 —— 從消息中心和通知，到工作區和應用列表。它弱化了審美效果，包含了這樣的道理：幫助用户專注於最重要的部分。</p><p>但是對我而言，我的桌面需要的不僅僅是一個美化的相框。</p><h3 id="gnome-shell之美" tabindex="-1">GNOME Shell之美 <a class="header-anchor" href="#gnome-shell之美" aria-label="Permalink to “GNOME Shell之美”">​</a></h3><p>拋開我自己的偏好，隱藏應用是GNOME Shell之美的一部分。它帶來了默認的桌面體驗：用户友好，穩健以及可預見性——而且也完全可擴展。因此，它也附帶有大量的擴展組件以迎合不同用户的需要、職業和希望，包括傳統應用菜單，桌面停靠欄，以及甚至是Ubuntu Unity Dash的複製品！</p><p>在本文中，我僅僅關注那個能滿足我需要的擴展：它有個恰如其分的名字<strong>Simple Dock</strong>。Simple Dock獲取GNOME Shell應用網格以及收藏欄，並可以將它放到任何我想要放的不引人注目的位置：桌面上。</p><p>目前為止，它只支持放置在屏幕底部，只提供了最小的設置項。雖然是最小的，但我覺得所有這些設置已經能滿足我的需要：</p><ul><li>智能自動隱藏</li><li>最小化/還原應用窗口</li><li>拖放收藏</li><li>覆蓋活動啓動按鈕</li></ul><p>你也想要嗎？如果你正在Ubuntu 13.10或更高版本上使用GNOME Shell，那麼你可以使用它。只需在支持的瀏覽器（Firefox, GNOME Web之類）中訪問下面的鏈接就可以導航到GNOME擴展頁面，然後將頁面上開個從“off”拖動到“on”上。</p>',12)),t("ul",null,[t("li",null,[n(o,{href:"https://extensions.gnome.org/extension/815/simple-dock/"},{default:p(()=>[...e[0]||(e[0]=[l("GNOME Shell擴展中的Simple Dock",-1)])]),_:1})])]),e[13]||(e[13]=t("p",null,"要調整Simple Dock設置，點擊GNOME擴展頁面上的齒輪圖標，或者通過GNOME優化工具這樣的桌面應用程序來設置。",-1)),e[14]||(e[14]=t("hr",null,null,-1)),t("p",null,[e[2]||(e[2]=l("via: ",-1)),n(o,{href:"http://www.omgubuntu.co.uk/2014/07/simple-dock-gnome-shell-extension"},{default:p(()=>[...e[1]||(e[1]=[l("http://www.omgubuntu.co.uk/2014/07/simple-dock-gnome-shell-extension",-1)])]),_:1})]),t("p",null,[e[5]||(e[5]=l("譯者：",-1)),n(o,{href:"https://github.com/GOLinux"},{default:p(()=>[...e[3]||(e[3]=[l("GOLinux",-1)])]),_:1}),e[6]||(e[6]=l(" 校對：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...e[4]||(e[4]=[l("Caroline",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=l("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[7]||(e[7]=[l("LCTT",-1)])]),_:1}),e[10]||(e[10]=l(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:p(()=>[...e[8]||(e[8]=[l("Linux中國",-1)])]),_:1}),e[11]||(e[11]=l(" 榮譽推出",-1))])])}const f=s(m,[["render",S]]);export{T as __pageData,f as default};
